  /* ---------- media modal ---------- */
  function mediaModal(o) {
    var p = P(o.id);
    if (!p) return '';
    var gal = p.gallery || [p.image];
    var tabs = [['all', 'All media'], ['video', 'Video'], ['measurement', 'Measurement']];
